// Structure of a binary tree node
class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int x) {
        data = x;
        left = nullptr;
        right = nullptr;
    }
};

// Returns the maximum width of the binary tree
int maxWidth(Node* root) {

    if (root == nullptr)
        return 0;

    queue<Node*> q;
    q.push(root);

    int ans = 0;

    while (!q.empty()) {

        // Number of nodes at current level
        int count = q.size();

        // Update maximum width
        ans = max(ans, count);

        // Process all nodes of current level
        while (count--) {

            Node* curr = q.front();
            q.pop();

            // Add left child
            if (curr->left)
                q.push(curr->left);

            // Add right child
            if (curr->right)
                q.push(curr->right);
        }
    }

    return ans;
}

